/**
 * Every image on the site, with its alt text. Entries with `placeholder: true` are stand-in illustrations
 * (generated by scripts/generate-placeholder-images.mjs) shown with a badge until the real photo or screenshot
 * arrives. To use a real image: add it under public/images/, change `src`, and delete `placeholder`.
 */
export type SiteImageData = { src: string; alt: string; placeholder?: true };

const ph = (name: string) => `/images/placeholders/${name}.svg`;

